1	# daily-backup.ps1 — KeystoneOS durability automation
2	# Runs daily at 00:30 via scheduled task "KeystoneOS-DailyBackup".
3	#
4	# Jobs:
5	#   1. Git-sync the memory repos (auto-commit + push). Git history is the review
6	#      trail — an accidental deletion is recoverable from any prior commit.
7	#   2. Snapshot non-git stores to the cloud targets.
8	#   3. Manifest-driven coverage (added 2026-08-03). See backup-manifest.json.
9	#
10	# COVERAGE MODEL — read this before changing anything above.
11	# Until 2026-08-03 this script chose a mechanism by asking "is it a git repo?".
12	# That proxy silently dropped 4.13 GB across 8,883 files: gitignored data inside
13	# git repos is pushed by neither `git push` nor the non-repo snapshot. A second,
14	# narrower gap was uncommitted edits to tracked files. Three states now exist and
15	# all three must be covered:
16	#
17	#   tracked + committed + pushed  -> GitHub
18	#   untracked or ignored          -> SSD (captureOrphans)
19	#   tracked + modified            -> SSD (captureWorkingTree)
20	#
21	# backup-manifest.json is the single authority. It is DEFAULT-DENY: a DEV
22	# directory absent from it raises an error rather than being silently skipped.
23	# Never reintroduce repo-detection as a coverage test.
24	#
25	# Failures append ONE line to global-memory\transcripts\.errors.log, which every
26	# Claude session surfaces at startup. Full detail: scripts\logs\daily-backup.log.
27	
28	param([switch]$DryRun)
29	
30	$ErrorActionPreference = 'Continue'
31	$U = $env:USERPROFILE
32	$LogDir = "$U\.claude\scripts\logs"
33	$LogFile = "$LogDir\daily-backup.log"
34	$StateFile = "$LogDir\backup-state.json"
35	$ErrorsLog = "$U\.claude\global-memory\transcripts\.errors.log"
36	$Errors = [System.Collections.Generic.List[string]]::new()
37	$Results = [System.Collections.Generic.List[object]]::new()
38	
39	New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
40	
41	function Log($msg) {
42	    $line = "{0} {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
43	    Add-Content -Path $LogFile -Value $line
44	    Write-Output $line
45	}
46	
47	function Sync-Repo($path, $branch) {
48	    $name = Split-Path $path -Leaf
49	    if ($path -eq "$U\.claude") { $name = 'dotclaude' }
50	    if (-not (Test-Path (Join-Path $path '.git'))) { $Errors.Add("repo-missing:$name"); return }
51	    Push-Location $path
52	    try {
53	        git fetch origin 2>&1 | Out-Null
54	        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
55	        $behind = 0; $ahead = 0
56	        if ($counts) { $p = $counts -split '\s+'; $behind = [int]$p[0]; $ahead = [int]$p[1] }
57	        $dirty = (git status --porcelain | Measure-Object).Count
58	
59	        if ($behind -gt 0 -and ($ahead -gt 0 -or $dirty -gt 0)) {
60	            # Diverged with local changes: never merge blindly from automation.
61	            $Errors.Add("repo-diverged:$name")
62	            Log "REPO $name : DIVERGED (behind=$behind ahead=$ahead dirty=$dirty) - manual reconcile needed"
63	            return
64	        }
65	        if ($behind -gt 0) {
66	            if (-not $DryRun) { git pull --ff-only origin $branch 2>&1 | Out-Null }
67	            Log "REPO $name : fast-forwarded $behind commit(s)"
68	        }
69	        if ($dirty -gt 0) {
70	            if (-not $DryRun) {
71	                git add -A 2>&1 | Out-Null
72	                git commit -m ("chore: daily backup sync {0} [auto]" -f (Get-Date -Format 'yyyy-MM-dd')) 2>&1 | Out-Null
73	            }
74	            Log "REPO $name : committed $dirty change(s)"
75	        }
76	        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
77	        $ahead = if ($counts) { [int](($counts -split '\s+')[1]) } else { 0 }
78	        if ($DryRun -and $dirty -gt 0) { $ahead = 1 }
79	        if ($ahead -gt 0) {
80	            if (-not $DryRun) {
81	                git push origin $branch 2>&1 | Out-Null
82	                if ($LASTEXITCODE -ne 0) { $Errors.Add("repo-push:$name"); Log "REPO $name : PUSH FAILED"; return }
83	            }
84	            Log "REPO $name : pushed"
85	        }
86	        $Results.Add(@{ kind='repo'; name=$name; status='OK' })
87	    } finally { Pop-Location }
88	}
89	
90	function Snapshot($src, $dst, [string[]]$extraXD) {
91	    if (-not (Test-Path $src)) { Log "SNAP skip (missing): $src"; return }
92	    $xd = @('node_modules', '.venv', '__pycache__', '.git', 'cache', 'tmp') + $extraXD
93	    $args = @($src, $dst, '/MIR', '/R:2', '/W:5', '/NFL', '/NDL', '/NP', '/NJH') + ($xd | ForEach-Object { @('/XD', $_) })
94	    if ($DryRun) { $args += '/L' }
95	    robocopy @args | Select-Object -Last 6 | Add-Content -Path $LogFile
96	    if ($LASTEXITCODE -ge 8) {
97	        $Errors.Add("snapshot:$([IO.Path]::GetFileName($dst))")
98	        Log "SNAP $src -> $dst : FAILED (robocopy exit $LASTEXITCODE)"
99	    } else {
100	        Log "SNAP $src -> $dst : OK (exit $LASTEXITCODE)"
101	        $Results.Add(@{ kind='snapshot'; name=$dst; status='OK' })
102	    }
103	}
104	
105	# --- Manifest-driven coverage (2026-08-03) ---
106	
107	$ManifestFile = "$U\.claude\scripts\backup-manifest.json"
108	$Manifest = $null
109	if (Test-Path $ManifestFile) {
110	    try { $Manifest = Get-Content -Raw $ManifestFile | ConvertFrom-Json }
111	    catch { $Errors.Add('manifest-unreadable'); }
112	}
113	
114	# CREDENTIAL DENY-LIST — applies to every capture path. Do not weaken.
115	#
116	# Files are gitignored for two OPPOSITE reasons: "too big / regenerable" (we DO want
117	# these backed up — that was the whole point of the 2026-08-03 orphan capture) and
118	# "must never leave this machine" (we must NOT). Capturing by "what git ignores"
119	# treats them identically and silently inverts the credential-exclusion policy that
120	# RESTORE.md and CREDENTIALS.md both state.
121	#
122	# Found 2026-08-04, pre-migration: 7,633 files / 391.6 MB of
123	# morning-briefing\secrets\owa-profile — a live authenticated Outlook browser profile
124	# including Cookies, Login Data and Local State — had been copied to a portable drive
125	# that was about to leave the building. Purged. This list is why it cannot recur.
126	$CredDenyDirs  = @('secrets', 'owa-profile', 'edge-profile', 'chrome-profile', '.aws', '.ssh')
127	$CredDenyFiles = @('.env', '.env.local', '.env.production', '.env.production.local',
128	                   'Cookies', 'Login Data', 'Local State', '.credentials.json',
129	                   'gmail_token.json', 'gmail_credentials.json', 'token.json', 'credentials.json')
130	# Regex form for the file-by-file capture path. '.env.example' is deliberately NOT
131	# denied: it holds key NAMES only and is what makes a restore reconstructable.
132	$CredDenyRe = '(^|\\)(secrets|owa-profile|edge-profile|chrome-profile|\.aws|\.ssh)(\\|$)' +
133	              '|(^|\\)\.env(\.local|\.production(\.local)?)?$' +
134	              '|(^|\\)(Cookies|Login Data|Local State)$' +
135	              '|(^|\\)(\.credentials|gmail_token|gmail_credentials|token|credentials)\.json$'
136	
137	# Additive copy: no /MIR. A mirror faithfully replicates the deletion you are
138	# trying to recover from, so the survivor-grade store never propagates deletes.
139	function Snapshot-Additive($src, $dst, [string[]]$extraXD) {
140	    if (-not (Test-Path $src)) { return $false }
141	    $xd = @('node_modules', '.venv', 'venv', '__pycache__', '.next', 'dist', '.pytest_cache') + $CredDenyDirs + $extraXD
142	    $a = @($src, $dst, '/E', '/R:1', '/W:1', '/NFL', '/NDL', '/NP', '/NJH', '/NJS') +
143	         ($xd | ForEach-Object { @('/XD', $_) }) + ($CredDenyFiles | ForEach-Object { @('/XF', $_) })
144	    if ($DryRun) { $a += '/L' }
145	    $null = robocopy @a
146	    return ($LASTEXITCODE -lt 8)
147	}
148	
149	# Capture what git will never carry: untracked/ignored files, and uncommitted
150	# edits to tracked files. Authoritative source is git itself, not a path regex —
151	# an approximated .gitignore will drift from the real rules.
152	function Capture-RepoData($repoPath, $repoName, $ssdRoot) {
153	    # Rebuildable dirs OR anything on the credential deny-list. The deny-list is the
154	    # security boundary here: this function's whole job is to capture gitignored files,
155	    # and 'secrets/' is gitignored precisely because it must never be copied.
156	    $skipRe = '(^|\\)(node_modules|\.venv|venv|__pycache__|\.next|dist|\.pytest_cache)(\\|$)' + '|' + $CredDenyRe
157	    $copied = 0
158	    $denied = 0
159	
160	    $orphans = @()
161	    $orphans += (git -C $repoPath ls-files --others --exclude-standard 2>$null)
162	    $orphans += (git -C $repoPath ls-files --others --ignored --exclude-standard 2>$null)
163	    foreach ($rel in ($orphans | Where-Object { $_ } | Sort-Object -Unique)) {
164	        $w = $rel -replace '/', '\'
165	        if ($w -match $skipRe) { if ($w -match $CredDenyRe) { $denied++ }; continue }
166	        $s = Join-Path $repoPath $w
167	        if (-not (Test-Path -LiteralPath $s -PathType Leaf)) { continue }
168	        $d = Join-Path $ssdRoot "DEV-repo-data\$repoName\$w"
169	        if (-not $DryRun) {
170	            New-Item -ItemType Directory -Force -Path (Split-Path $d -Parent) | Out-Null
171	            try { Copy-Item -LiteralPath $s -Destination $d -Force -EA Stop; $copied++ } catch {}
172	        } else { $copied++ }
173	    }
174	
175	    # Uncommitted edits to tracked files: GitHub holds only the last committed state.
176	    foreach ($rel in (git -C $repoPath diff --name-only 2>$null)) {
177	        $w = $rel -replace '/', '\'
178	        $s = Join-Path $repoPath $w
179	        if (-not (Test-Path -LiteralPath $s -PathType Leaf)) { continue }
180	        $d = Join-Path $ssdRoot "DEV-working-tree\$repoName\$w"
181	        if (-not $DryRun) {
182	            New-Item -ItemType Directory -Force -Path (Split-Path $d -Parent) | Out-Null
183	            try { Copy-Item -LiteralPath $s -Destination $d -Force -EA Stop; $copied++ } catch {}
184	        } else { $copied++ }
185	    }
186	    if ($denied -gt 0) { Log "  DENY $repoName : $denied credential file(s) excluded by policy" }
187	    return $copied
188	}
189	
190	# A receipt proves the destination accepted a write in THIS run. Exit code 0 can
191	# be produced by a run that did nothing; a sentinel read back cannot.
192	function Write-Receipt($root, $runId) {
193	    if ($DryRun) { return $true }
194	    try {
195	        $rd = Join-Path $root '_receipts'
196	        New-Item -ItemType Directory -Force -Path $rd | Out-Null
197	        $f = Join-Path $rd "run-$runId.txt"
198	        Set-Content -LiteralPath $f -Value "run=$runId written=$(Get-Date -Format 'o') host=$env:COMPUTERNAME" -Encoding UTF8
199	        $back = Get-Content -LiteralPath $f -Raw
200	        return ($back -match [regex]::Escape($runId))
201	    } catch { return $false }
202	}
203	
204	$RunId = (Get-Date -Format 'yyyyMMdd-HHmmss')
205	
206	Log "===== daily-backup start (DryRun=$DryRun) run=$RunId ====="
207	
208	# --- 1. Git memory repos ---
209	Sync-Repo "$U\Desktop\SecondBrain"      'main'
210	Sync-Repo "$U\.claude\global-memory"    'main'
211	Sync-Repo "$U\.claude"                  'main'
212	Sync-Repo "$U\.claude\skills"           'main'
213	
214	# --- 2a. Personal-context snapshots -> personal Google Drive (gmail) ---
215	# NOT OneDrive: the personal OneDrive account is not signed in on this machine
216	# (discovered 2026-07-23 — that folder is a dead local dir), and Google is the
217	# durable personal identity that survives any institutional change.
218	$P = 'G:\My Drive\Backups\Machine'
219	if (-not (Test-Path 'G:\My Drive')) {
220	    $Errors.Add('backup-target-offline:GoogleDrive')
221	    Log "TARGET G:\My Drive NOT MOUNTED - is Google Drive for Desktop running? Skipping personal snapshots."
222	}
223	Snapshot "$U\.claude\projects"  "$P\claude-projects"  @('worktrees')
224	Snapshot "$U\.codex\memories"   "$P\codex\memories"   @()
225	Snapshot "$U\.codex\sessions"   "$P\codex\sessions"   @()
226	Snapshot "$U\.codex\agents"     "$P\codex\agents"     @()
227	Snapshot "$U\.codex\sqlite"     "$P\codex\sqlite"     @()
228	Snapshot "$U\.gemini"           "$P\gemini"           @('antigravity_browser_profile')
229	
230	# --- 2b. Manifest-driven DEV coverage (replaces repo-detection, 2026-08-03) ---
231	$B = "$U\OneDrive - Baylor University\Backups\DEV-NonRepo"
232	$SsdRoot = $null
233	$SsdOnline = $false
234	
235	if ($Manifest) {
236	    $SsdRoot = $Manifest.destinations.ssd.root
237	    $SsdOnline = Test-Path $SsdRoot
238	    if (-not $SsdOnline) {
239	        # Optional destination: warn loudly, never fail silently, never block the run.
240	        $Errors.Add('backup-target-offline:SSD')
241	        Log "TARGET SSD $SsdRoot NOT MOUNTED - orphan and working-tree capture SKIPPED this run"
242	    }
243	
244	    # DEFAULT-DENY: a DEV directory absent from the manifest is an error, not a skip.
245	    $declared = @($Manifest.paths | Where-Object { $_.path -like 'DEV/*' } | ForEach-Object { $_.path -replace '^DEV/', '' })
246	    $onDisk = @(Get-ChildItem "$U\Desktop\DEV" -Directory | Where-Object { $_.Name -notmatch '^\.' } | Select-Object -ExpandProperty Name)
247	    $unmanaged = @($onDisk | Where-Object { $declared -notcontains $_ })
248	    if ($unmanaged.Count -gt 0) {
249	        $Errors.Add("manifest-unmanaged:$($unmanaged -join '|')")
250	        Log "MANIFEST $($unmanaged.Count) unmanaged DEV dir(s): $($unmanaged -join ', ') - add to backup-manifest.json"
251	    }
252	    $missing = @($declared | Where-Object { $onDisk -notcontains $_ })
253	    if ($missing.Count -gt 0) { Log "MANIFEST $($missing.Count) declared dir(s) absent from disk: $($missing -join ', ')" }
254	
255	    foreach ($entry in ($Manifest.paths | Where-Object { $_.path -like 'DEV/*' })) {
256	        $name = $entry.path -replace '^DEV/', ''
257	        $src = "$U\Desktop\DEV\$name"
258	        if (-not (Test-Path $src)) { continue }
259	
260	        # Whole-folder snapshot for anything GitHub does not carry.
261	        if (-not $entry.isRepo) {
262	            if ($SsdOnline) {
263	                $ok = Snapshot-Additive $src (Join-Path $SsdRoot "DEV-nonrepo\$name") @('.playwright-mcp')
264	                if (-not $ok) { $Errors.Add("snapshot-ssd:$name") }
265	            }
266	            if ($entry.destinations -contains 'baylor' -and (Test-Path (Split-Path $B -Parent))) {
267	                Snapshot $src "$B\$name" @('.playwright-mcp')
268	            }
269	        }
270	        # Repos: capture exactly what git cannot.
271	        elseif ($SsdOnline -and ($entry.captureOrphans -or $entry.captureWorkingTree)) {
272	            $n = Capture-RepoData $src $name $SsdRoot
273	            if ($n -gt 0) { Log "CAPTURE $name : $n file(s) git does not carry" }
274	            $Results.Add(@{ kind = 'capture'; name = $name; status = 'OK' })
275	        }
276	    }
277	
278	    # Non-DEV manifest paths (~/.claude subtrees, .codex, .gemini, SecondBrain) -> SSD.
279	    # These were declared in the manifest from the start but the loop above filters on
280	    # 'DEV/*', so they were inert: the cloud snapshots in 2a kept Google Drive current
281	    # while the SSD copy stayed frozen at the Phase 1 rescue. Found 2026-08-04 when the
282	    # SSD held 1,596 conversation files against 1,630 on disk — and MIGRATION-MACOS.md
283	    # Step 3 restores conversation history from the SSD, not from Drive.
284	    if ($SsdOnline) {
285	        foreach ($entry in ($Manifest.paths | Where-Object { $_.path -notlike 'DEV/*' -and $_.destinations -contains 'ssd' })) {
286	            $rel = $entry.path -replace '/', '\'
287	            $src = Join-Path $U $rel
288	            if (-not (Test-Path $src)) { continue }
289	            $leaf = Split-Path $rel -Leaf
290	            $sub = switch -Wildcard ($entry.path) {
291	                '.claude/*'  { "claude\$leaf" }
292	                'Desktop/*'  { $leaf }
293	                default      { $leaf -replace '^\.', '' }
294	            }
295	            $extra = @()
296	            if ($entry.path -eq '.codex') { $extra = @('work') }
297	            if ($entry.path -eq '.gemini') { $extra = @('antigravity_browser_profile') }
298	            if ($entry.path -like 'Desktop/*') { $extra = @('.git') }
299	            $ok = Snapshot-Additive $src (Join-Path $SsdRoot $sub) $extra
300	            if ($ok) { Log "STATE-SSD $($entry.path) -> $sub : OK" }
301	            else { $Errors.Add("snapshot-ssd:$($entry.path)"); Log "STATE-SSD $($entry.path) : FAILED" }
302	        }
303	    }
304	
305	    # Receipts: prove each destination accepted a write in THIS run.
306	    foreach ($dn in @('ssd', 'drive')) {
307	        $root = $Manifest.destinations.$dn.root
308	        if (-not $root -or -not (Test-Path $root)) { continue }
309	        if ($DryRun) { Log "RECEIPT $dn : skipped (dry run wrote nothing to verify)"; continue }
310	        if (Write-Receipt $root $RunId) { Log "RECEIPT $dn : verified run=$RunId" }
311	        else { $Errors.Add("receipt-failed:$dn"); Log "RECEIPT $dn : FAILED - destination did not read back the sentinel" }
312	    }
313	}
314	else {
315	    # Manifest missing: fall back to old behaviour but make the degradation loud.
316	    $Errors.Add('manifest-missing')
317	    Log "MANIFEST not found at $ManifestFile - falling back to repo-detection (KNOWN TO UNDER-COVER by ~4 GB)"
318	    Get-ChildItem "$U\Desktop\DEV" -Directory |
319	        Where-Object { -not (Test-Path (Join-Path $_.FullName '.git')) -and $_.Name -notmatch '^\.' } |
320	        ForEach-Object { Snapshot $_.FullName "$B\$($_.Name)" @('.playwright-mcp') }
321	}
322	
323	# --- 2c. Full memsearch reindex (no session-time cap) ---
324	# The SessionEnd hook indexes incrementally under a 45s cap - enough for normal
325	# session deltas, never for heavy days (a 41-chunk backlog on 7/24 needed >10 min
326	# at ONNX embedding speed). This nightly pass absorbs any backlog and resets the
327	# hook's consecutive-timeout alarm so mornings start clean.
328	$msExe = "$U\AppData\Roaming\Python\Python314\Scripts\memsearch.exe"
329	if (-not (Test-Path $msExe)) { $msExe = (Get-Command memsearch -ErrorAction SilentlyContinue).Source }
330	if ($msExe -and -not $DryRun) {
331	    $msFail = $false
332	    # Single source of truth: KeystoneOS declares the index set in
333	    # data\memory-index-paths.json (AGENTS.md routes "Memory index path templates"
334	    # there). This list used to be hardcoded here and had silently diverged from
335	    # that file - three declared paths (KeystoneOS project memory, Inbox\meetings,
336	    # .codex\memories) were never actually indexed by this nightly pass, so the
337	    # registry described an index that did not exist. Read it instead.
338	    $msPathsFallback = @(
339	        "$U\.claude\global-memory\transcripts",
340	        "$U\.claude\projects\C--Users-eric-rash\memory",
341	        "$U\.claude\claude-memory-compiler\daily",
342	        "$U\.claude\claude-memory-compiler\knowledge",
343	        "$U\Desktop\SecondBrain\Knowledge"
344	    )
345	    $msConfig = "$U\Desktop\DEV\KeystoneOS\data\memory-index-paths.json"
346	    $msPaths = $null
347	    if (Test-Path -LiteralPath $msConfig) {
348	        try {
349	            $declared = (Get-Content -Raw -LiteralPath $msConfig | ConvertFrom-Json).paths
350	            if ($declared -and $declared.Count -ge 1) {
351	                $msPaths = @($declared | ForEach-Object { ($_ -replace '\{HOME\}', $U) -replace '/', '\' })
352	                Log "INDEX path set: $($msPaths.Count) paths from memory-index-paths.json"
353	            }
354	        } catch { Log "INDEX config unreadable ($($_.Exception.Message)) - using built-in fallback list" }
355	    }
356	    if (-not $msPaths) {
357	        $msPaths = $msPathsFallback
358	        $Errors.Add('memsearch-index-config-missing')
359	        Log "INDEX path set: built-in fallback ($($msPaths.Count) paths) - memory-index-paths.json not usable"
360	    }
361	    # The backup's full reindex shares the SessionEnd hook's lock. Without this,
362	    # the nightly pass can run beside Claude/Codex hooks and multiply the Python
363	    # embedding workers. Reclaim only a dead owner; indexers can exceed 30s.
364	    $indexLockFile = "$U\.claude\global-memory\transcripts\.memsearch-index.lock"
365	    $indexLockStaleMs = 5 * 60 * 1000
366	    $haveIndexLock = $false
367	    try {
368	        $lockStream = [System.IO.File]::Open($indexLockFile, [System.IO.FileMode]::CreateNew)
369	        $lockStream.Close()
370	        [System.IO.File]::WriteAllText($indexLockFile, [string]$PID)
371	        $haveIndexLock = $true
372	    }
373	    catch {
374	        $ownerAlive = $false
375	        try {
376	            $ownerPid = [int](Get-Content -Raw -LiteralPath $indexLockFile)
377	            $null = Get-Process -Id $ownerPid -ErrorAction Stop
378	            $ownerAlive = $true
379	        } catch {}
380	        if (-not $ownerAlive) {
381	            $lockStale = $false
382	            try { $lockStale = (((Get-Date) - (Get-Item -LiteralPath $indexLockFile).LastWriteTime).TotalMilliseconds -ge $indexLockStaleMs) }
383	            catch { $lockStale = $true }
384	            if ($lockStale) {
385	                try {
386	                    Remove-Item -LiteralPath $indexLockFile -Force -ErrorAction Stop
387	                    $lockStream = [System.IO.File]::Open($indexLockFile, [System.IO.FileMode]::CreateNew)
388	                    $lockStream.Close()
389	                    [System.IO.File]::WriteAllText($indexLockFile, [string]$PID)
390	                    $haveIndexLock = $true
391	                } catch {}
392	            }
393	        }
394	    }
395	
396	    if (-not $haveIndexLock) {
397	        Log "INDEX skipped - another index run is active; next hook/nightly pass will catch up"
398	    }
399	    else {
400	        try {
401	            $existingPaths = @($msPaths | Where-Object { Test-Path $_ })
402	            if ($existingPaths.Count -gt 0) {
403	                $r = & $msExe index $existingPaths 2>&1 | Select-Object -Last 1
404	                Log "INDEX full set: $r"
405	                if ($LASTEXITCODE -ne 0) { $msFail = $true; $Errors.Add("memsearch-index:full-set") }
406	            }
407	        }
408	        finally {
409	            Remove-Item -LiteralPath $indexLockFile -Force -ErrorAction SilentlyContinue
410	        }
411	    }
412	    if (-not $msFail -and $haveIndexLock) {
413	        Remove-Item "$U\.claude\global-memory\transcripts\.memsearch-timeout-streak" -Force -ErrorAction SilentlyContinue
414	        Log "INDEX complete - hook timeout-streak counter reset"
415	    }
416	} elseif (-not $msExe) { $Errors.Add('memsearch-exe-missing'); Log "INDEX skipped: memsearch.exe not found" }
417	
418	# --- 2d. Mirror the recovery guide to the cloud backup root ---
419	if ((Test-Path 'G:\My Drive') -and (Test-Path "$U\.claude\RESTORE.md") -and -not $DryRun) {
420	    New-Item -ItemType Directory -Force -Path 'G:\My Drive\Backups' | Out-Null
421	    Copy-Item "$U\.claude\RESTORE.md" 'G:\My Drive\Backups\RESTORE.md' -Force
422	    Log "RESTORE.md mirrored to G:\My Drive\Backups\"
423	}
424	
425	# --- 3. State + escalation ---
426	$status = if ($Errors.Count -eq 0) { 'OK' } else { 'ERROR' }
427	@{
428	    lastRun  = (Get-Date -Format 'o')
429	    status   = $status
430	    errors   = @($Errors)
431	    okCount  = $Results.Count
432	    dryRun   = [bool]$DryRun
433	} | ConvertTo-Json | Set-Content -Path $StateFile
434	
435	if ($Errors.Count -gt 0 -and -not $DryRun) {
436	    $line = "[{0}] daily-backup: {1} error(s): {2} - see ~\.claude\scripts\logs\daily-backup.log" -f (Get-Date -Format 'yyyy-MM-dd HH:mm'), $Errors.Count, ($Errors -join ', ')
437	    Add-Content -Path $ErrorsLog -Value $line
438	}
439	
440	# Keep the log from growing unbounded.
441	if ((Get-Item $LogFile).Length -gt 2MB) {
442	    Get-Content $LogFile -Tail 2000 | Set-Content $LogFile
443	}
444	
445	Log "===== daily-backup end: $status ($($Errors.Count) errors) ====="
446	if ($Errors.Count -gt 0) { exit 1 } else { exit 0 }
447

file.content:
# daily-backup.ps1 — KeystoneOS durability automation
# Runs daily at 00:30 via scheduled task "KeystoneOS-DailyBackup".
#
# Jobs:
#   1. Git-sync the memory repos (auto-commit + push). Git history is the review
#      trail — an accidental deletion is recoverable from any prior commit.
#   2. Snapshot non-git stores to the cloud targets.
#   3. Manifest-driven coverage (added 2026-08-03). See backup-manifest.json.
#
# COVERAGE MODEL — read this before changing anything above.
# Until 2026-08-03 this script chose a mechanism by asking "is it a git repo?".
# That proxy silently dropped 4.13 GB across 8,883 files: gitignored data inside
# git repos is pushed by neither `git push` nor the non-repo snapshot. A second,
# narrower gap was uncommitted edits to tracked files. Three states now exist and
# all three must be covered:
#
#   tracked + committed + pushed  -> GitHub
#   untracked or ignored          -> SSD (captureOrphans)
#   tracked + modified            -> SSD (captureWorkingTree)
#
# backup-manifest.json is the single authority. It is DEFAULT-DENY: a DEV
# directory absent from it raises an error rather than being silently skipped.
# Never reintroduce repo-detection as a coverage test.
#
# Failures append ONE line to global-memory\transcripts\.errors.log, which every
# Claude session surfaces at startup. Full detail: scripts\logs\daily-backup.log.

param([switch]$DryRun)

$ErrorActionPreference = 'Continue'
$U = $env:USERPROFILE
$LogDir = "$U\.claude\scripts\logs"
$LogFile = "$LogDir\daily-backup.log"
$StateFile = "$LogDir\backup-state.json"
$ErrorsLog = "$U\.claude\global-memory\transcripts\.errors.log"
$Errors = [System.Collections.Generic.List[string]]::new()
$Results = [System.Collections.Generic.List[object]]::new()

New-Item -ItemType Directory -Force -Path $LogDir | Out-Null

function Log($msg) {
    $line = "{0} {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
    Add-Content -Path $LogFile -Value $line
    Write-Output $line
}

function Sync-Repo($path, $branch) {
    $name = Split-Path $path -Leaf
    if ($path -eq "$U\.claude") { $name = 'dotclaude' }
    if (-not (Test-Path (Join-Path $path '.git'))) { $Errors.Add("repo-missing:$name"); return }
    Push-Location $path
    try {
        git fetch origin 2>&1 | Out-Null
        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
        $behind = 0; $ahead = 0
        if ($counts) { $p = $counts -split '\s+'; $behind = [int]$p[0]; $ahead = [int]$p[1] }
        $dirty = (git status --porcelain | Measure-Object).Count

        if ($behind -gt 0 -and ($ahead -gt 0 -or $dirty -gt 0)) {
            # Diverged with local changes: never merge blindly from automation.
            $Errors.Add("repo-diverged:$name")
            Log "REPO $name : DIVERGED (behind=$behind ahead=$ahead dirty=$dirty) - manual reconcile needed"
            return
        }
        if ($behind -gt 0) {
            if (-not $DryRun) { git pull --ff-only origin $branch 2>&1 | Out-Null }
            Log "REPO $name : fast-forwarded $behind commit(s)"
        }
        if ($dirty -gt 0) {
            if (-not $DryRun) {
                git add -A 2>&1 | Out-Null
                git commit -m ("chore: daily backup sync {0} [auto]" -f (Get-Date -Format 'yyyy-MM-dd')) 2>&1 | Out-Null
            }
            Log "REPO $name : committed $dirty change(s)"
        }
        $counts = git rev-list --left-right --count "origin/$branch...HEAD" 2>$null
        $ahead = if ($counts) { [int](($counts -split '\s+')[1]) } else { 0 }
        if ($DryRun -and $dirty -gt 0) { $ahead = 1 }
        if ($ahead -gt 0) {
            if (-not $DryRun) {
                git push origin $branch 2>&1 | Out-Null
                if ($LASTEXITCODE -ne 0) { $Errors.Add("repo-push:$name"); Log "REPO $name : PUSH FAILED"; return }
            }
            Log "REPO $name : pushed"
        }
        $Results.Add(@{ kind='repo'; name=$name; status='OK' })
    } finally { Pop-Location }
}

function Snapshot($src, $dst, [string[]]$extraXD) {
    if (-not (Test-Path $src)) { Log "SNAP skip (missing): $src"; return }
    $xd = @('node_modules', '.venv', '__pycache__', '.git', 'cache', 'tmp') + $extraXD
    $args = @($src, $dst, '/MIR', '/R:2', '/W:5', '/NFL', '/NDL', '/NP', '/NJH') + ($xd | ForEach-Object { @('/XD', $_) })
    if ($DryRun) { $args += '/L' }
    robocopy @args | Select-Object -Last 6 | Add-Content -Path $LogFile
    if ($LASTEXITCODE -ge 8) {
        $Errors.Add("snapshot:$([IO.Path]::GetFileName($dst))")
        Log "SNAP $src -> $dst : FAILED (robocopy exit $LASTEXITCODE)"
    } else {
        Log "SNAP $src -> $dst : OK (exit $LASTEXITCODE)"
        $Results.Add(@{ kind='snapshot'; name=$dst; status='OK' })
    }
}

# --- Manifest-driven coverage (2026-08-03) ---

$ManifestFile = "$U\.claude\scripts\backup-manifest.json"
$Manifest = $null
if (Test-Path $ManifestFile) {
    try { $Manifest = Get-Content -Raw $ManifestFile | ConvertFrom-Json }
    catch { $Errors.Add('manifest-unreadable'); }
}

# CREDENTIAL DENY-LIST — applies to every capture path. Do not weaken.
#
# Files are gitignored for two OPPOSITE reasons: "too big / regenerable" (we DO want
# these backed up — that was the whole point of the 2026-08-03 orphan capture) and
# "must never leave this machine" (we must NOT). Capturing by "what git ignores"
# treats them identically and silently inverts the credential-exclusion policy that
# RESTORE.md and CREDENTIALS.md both state.
#
# Found 2026-08-04, pre-migration: 7,633 files / 391.6 MB of
# morning-briefing\secrets\owa-profile — a live authenticated Outlook browser profile
# including Cookies, Login Data and Local State — had been copied to a portable drive
# that was about to leave the building. Purged. This list is why it cannot recur.
$CredDenyDirs  = @('secrets', 'owa-profile', 'edge-profile', 'chrome-profile', '.aws', '.ssh')
$CredDenyFiles = @('.env', '.env.local', '.env.production', '.env.production.local',
                   'Cookies', 'Login Data', 'Local State', '.credentials.json',
                   'gmail_token.json', 'gmail_credentials.json', 'token.json', 'credentials.json')
# Regex form for the file-by-file capture path. '.env.example' is deliberately NOT
# denied: it holds key NAMES only and is what makes a restore reconstructable.
$CredDenyRe = '(^|\\)(secrets|owa-profile|edge-profile|chrome-profile|\.aws|\.ssh)(\\|$)' +
              '|(^|\\)\.env(\.local|\.production(\.local)?)?$' +
              '|(^|\\)(Cookies|Login Data|Local State)$' +
              '|(^|\\)(\.credentials|gmail_token|gmail_credentials|token|credentials)\.json$'

# Additive copy: no /MIR. A mirror faithfully replicates the deletion you are
# trying to recover from, so the survivor-grade store never propagates deletes.
function Snapshot-Additive($src, $dst, [string[]]$extraXD) {
    if (-not (Test-Path $src)) { return $false }
    $xd = @('node_modules', '.venv', 'venv', '__pycache__', '.next', 'dist', '.pytest_cache') + $CredDenyDirs + $extraXD
    $a = @($src, $dst, '/E', '/R:1', '/W:1', '/NFL', '/NDL', '/NP', '/NJH', '/NJS') +
         ($xd | ForEach-Object { @('/XD', $_) }) + ($CredDenyFiles | ForEach-Object { @('/XF', $_) })
    if ($DryRun) { $a += '/L' }
    $null = robocopy @a
    return ($LASTEXITCODE -lt 8)
}

# Capture what git will never carry: untracked/ignored files, and uncommitted
# edits to tracked files. Authoritative source is git itself, not a path regex —
# an approximated .gitignore will drift from the real rules.
function Capture-RepoData($repoPath, $repoName, $ssdRoot) {
    # Rebuildable dirs OR anything on the credential deny-list. The deny-list is the
    # security boundary here: this function's whole job is to capture gitignored files,
    # and 'secrets/' is gitignored precisely because it must never be copied.
    $skipRe = '(^|\\)(node_modules|\.venv|venv|__pycache__|\.next|dist|\.pytest_cache)(\\|$)' + '|' + $CredDenyRe
    $copied = 0
    $denied = 0

    $orphans = @()
    $orphans += (git -C $repoPath ls-files --others --exclude-standard 2>$null)
    $orphans += (git -C $repoPath ls-files --others --ignored --exclude-standard 2>$null)
    foreach ($rel in ($orphans | Where-Object { $_ } | Sort-Object -Unique)) {
        $w = $rel -replace '/', '\'
        if ($w -match $skipRe) { if ($w -match $CredDenyRe) { $denied++ }; continue }
        $s = Join-Path $repoPath $w
        if (-not (Test-Path -LiteralPath $s -PathType Leaf)) { continue }
        $d = Join-Path $ssdRoot "DEV-repo-data\$repoName\$w"
        if (-not $DryRun) {
            New-Item -ItemType Directory -Force -Path (Split-Path $d -Parent) | Out-Null
            try { Copy-Item -LiteralPath $s -Destination $d -Force -EA Stop; $copied++ } catch {}
        } else { $copied++ }
    }

    # Uncommitted edits to tracked files: GitHub holds only the last committed state.
    foreach ($rel in (git -C $repoPath diff --name-only 2>$null)) {
        $w = $rel -replace '/', '\'
        $s = Join-Path $repoPath $w
        if (-not (Test-Path -LiteralPath $s -PathType Leaf)) { continue }
        $d = Join-Path $ssdRoot "DEV-working-tree\$repoName\$w"
        if (-not $DryRun) {
            New-Item -ItemType Directory -Force -Path (Split-Path $d -Parent) | Out-Null
            try { Copy-Item -LiteralPath $s -Destination $d -Force -EA Stop; $copied++ } catch {}
        } else { $copied++ }
    }
    if ($denied -gt 0) { Log "  DENY $repoName : $denied credential file(s) excluded by policy" }
    return $copied
}

# A receipt proves the destination accepted a write in THIS run. Exit code 0 can
# be produced by a run that did nothing; a sentinel read back cannot.
function Write-Receipt($root, $runId) {
    if ($DryRun) { return $true }
    try {
        $rd = Join-Path $root '_receipts'
        New-Item -ItemType Directory -Force -Path $rd | Out-Null
        $f = Join-Path $rd "run-$runId.txt"
        Set-Content -LiteralPath $f -Value "run=$runId written=$(Get-Date -Format 'o') host=$env:COMPUTERNAME" -Encoding UTF8
        $back = Get-Content -LiteralPath $f -Raw
        return ($back -match [regex]::Escape($runId))
    } catch { return $false }
}

$RunId = (Get-Date -Format 'yyyyMMdd-HHmmss')

Log "===== daily-backup start (DryRun=$DryRun) run=$RunId ====="

# --- 1. Git memory repos ---
Sync-Repo "$U\Desktop\SecondBrain"      'main'
Sync-Repo "$U\.claude\global-memory"    'main'
Sync-Repo "$U\.claude"                  'main'
Sync-Repo "$U\.claude\skills"           'main'

# --- 2a. Personal-context snapshots -> personal Google Drive (gmail) ---
# NOT OneDrive: the personal OneDrive account is not signed in on this machine
# (discovered 2026-07-23 — that folder is a dead local dir), and Google is the
# durable personal identity that survives any institutional change.
$P = 'G:\My Drive\Backups\Machine'
if (-not (Test-Path 'G:\My Drive')) {
    $Errors.Add('backup-target-offline:GoogleDrive')
    Log "TARGET G:\My Drive NOT MOUNTED - is Google Drive for Desktop running? Skipping personal snapshots."
}
Snapshot "$U\.claude\projects"  "$P\claude-projects"  @('worktrees')
Snapshot "$U\.codex\memories"   "$P\codex\memories"   @()
Snapshot "$U\.codex\sessions"   "$P\codex\sessions"   @()
Snapshot "$U\.codex\agents"     "$P\codex\agents"     @()
Snapshot "$U\.codex\sqlite"     "$P\codex\sqlite"     @()
Snapshot "$U\.gemini"           "$P\gemini"           @('antigravity_browser_profile')

# --- 2b. Manifest-driven DEV coverage (replaces repo-detection, 2026-08-03) ---
$B = "$U\OneDrive - Baylor University\Backups\DEV-NonRepo"
$SsdRoot = $null
$SsdOnline = $false

if ($Manifest) {
    $SsdRoot = $Manifest.destinations.ssd.root
    $SsdOnline = Test-Path $SsdRoot
    if (-not $SsdOnline) {
        # Optional destination: warn loudly, never fail silently, never block the run.
        $Errors.Add('backup-target-offline:SSD')
        Log "TARGET SSD $SsdRoot NOT MOUNTED - orphan and working-tree capture SKIPPED this run"
    }

    # DEFAULT-DENY: a DEV directory absent from the manifest is an error, not a skip.
    $declared = @($Manifest.paths | Where-Object { $_.path -like 'DEV/*' } | ForEach-Object { $_.path -replace '^DEV/', '' })
    $onDisk = @(Get-ChildItem "$U\Desktop\DEV" -Directory | Where-Object { $_.Name -notmatch '^\.' } | Select-Object -ExpandProperty Name)
    $unmanaged = @($onDisk | Where-Object { $declared -notcontains $_ })
    if ($unmanaged.Count -gt 0) {
        $Errors.Add("manifest-unmanaged:$($unmanaged -join '|')")
        Log "MANIFEST $($unmanaged.Count) unmanaged DEV dir(s): $($unmanaged -join ', ') - add to backup-manifest.json"
    }
    $missing = @($declared | Where-Object { $onDisk -notcontains $_ })
    if ($missing.Count -gt 0) { Log "MANIFEST $($missing.Count) declared dir(s) absent from disk: $($missing -join ', ')" }

    foreach ($entry in ($Manifest.paths | Where-Object { $_.path -like 'DEV/*' })) {
        $name = $entry.path -replace '^DEV/', ''
        $src = "$U\Desktop\DEV\$name"
        if (-not (Test-Path $src)) { continue }

        # Whole-folder snapshot for anything GitHub does not carry.
        if (-not $entry.isRepo) {
            if ($SsdOnline) {
                $ok = Snapshot-Additive $src (Join-Path $SsdRoot "DEV-nonrepo\$name") @('.playwright-mcp')
                if (-not $ok) { $Errors.Add("snapshot-ssd:$name") }
            }
            if ($entry.destinations -contains 'baylor' -and (Test-Path (Split-Path $B -Parent))) {
                Snapshot $src "$B\$name" @('.playwright-mcp')
            }
        }
        # Repos: capture exactly what git cannot.
        elseif ($SsdOnline -and ($entry.captureOrphans -or $entry.captureWorkingTree)) {
            $n = Capture-RepoData $src $name $SsdRoot
            if ($n -gt 0) { Log "CAPTURE $name : $n file(s) git does not carry" }
            $Results.Add(@{ kind = 'capture'; name = $name; status = 'OK' })
        }
    }

    # Non-DEV manifest paths (~/.claude subtrees, .codex, .gemini, SecondBrain) -> SSD.
    # These were declared in the manifest from the start but the loop above filters on
    # 'DEV/*', so they were inert: the cloud snapshots in 2a kept Google Drive current
    # while the SSD copy stayed frozen at the Phase 1 rescue. Found 2026-08-04 when the
    # SSD held 1,596 conversation files against 1,630 on disk — and MIGRATION-MACOS.md
    # Step 3 restores conversation history from the SSD, not from Drive.
    if ($SsdOnline) {
        foreach ($entry in ($Manifest.paths | Where-Object { $_.path -notlike 'DEV/*' -and $_.destinations -contains 'ssd' })) {
            $rel = $entry.path -replace '/', '\'
            $src = Join-Path $U $rel
            if (-not (Test-Path $src)) { continue }
            $leaf = Split-Path $rel -Leaf
            $sub = switch -Wildcard ($entry.path) {
                '.claude/*'  { "claude\$leaf" }
                'Desktop/*'  { $leaf }
                default      { $leaf -replace '^\.', '' }
            }
            $extra = @()
            if ($entry.path -eq '.codex') { $extra = @('work') }
            if ($entry.path -eq '.gemini') { $extra = @('antigravity_browser_profile') }
            if ($entry.path -like 'Desktop/*') { $extra = @('.git') }
            $ok = Snapshot-Additive $src (Join-Path $SsdRoot $sub) $extra
            if ($ok) { Log "STATE-SSD $($entry.path) -> $sub : OK" }
            else { $Errors.Add("snapshot-ssd:$($entry.path)"); Log "STATE-SSD $($entry.path) : FAILED" }
        }
    }

    # Receipts: prove each destination accepted a write in THIS run.
    foreach ($dn in @('ssd', 'drive')) {
        $root = $Manifest.destinations.$dn.root
        if (-not $root -or -not (Test-Path $root)) { continue }
        if ($DryRun) { Log "RECEIPT $dn : skipped (dry run wrote nothing to verify)"; continue }
        if (Write-Receipt $root $RunId) { Log "RECEIPT $dn : verified run=$RunId" }
        else { $Errors.Add("receipt-failed:$dn"); Log "RECEIPT $dn : FAILED - destination did not read back the sentinel" }
    }
}
else {
    # Manifest missing: fall back to old behaviour but make the degradation loud.
    $Errors.Add('manifest-missing')
    Log "MANIFEST not found at $ManifestFile - falling back to repo-detection (KNOWN TO UNDER-COVER by ~4 GB)"
    Get-ChildItem "$U\Desktop\DEV" -Directory |
        Where-Object { -not (Test-Path (Join-Path $_.FullName '.git')) -and $_.Name -notmatch '^\.' } |
        ForEach-Object { Snapshot $_.FullName "$B\$($_.Name)" @('.playwright-mcp') }
}

# --- 2c. Full memsearch reindex (no session-time cap) ---
# The SessionEnd hook indexes incrementally under a 45s cap - enough for normal
# session deltas, never for heavy days (a 41-chunk backlog on 7/24 needed >10 min
# at ONNX embedding speed). This nightly pass absorbs any backlog and resets the
# hook's consecutive-timeout alarm so mornings start clean.
$msExe = "$U\AppData\Roaming\Python\Python314\Scripts\memsearch.exe"
if (-not (Test-Path $msExe)) { $msExe = (Get-Command memsearch -ErrorAction SilentlyContinue).Source }
if ($msExe -and -not $DryRun) {
    $msFail = $false
    # Single source of truth: KeystoneOS declares the index set in
    # data\memory-index-paths.json (AGENTS.md routes "Memory index path templates"
    # there). This list used to be hardcoded here and had silently diverged from
    # that file - three declared paths (KeystoneOS project memory, Inbox\meetings,
    # .codex\memories) were never actually indexed by this nightly pass, so the
    # registry described an index that did not exist. Read it instead.
    $msPathsFallback = @(
        "$U\.claude\global-memory\transcripts",
        "$U\.claude\projects\C--Users-eric-rash\memory",
        "$U\.claude\claude-memory-compiler\daily",
        "$U\.claude\claude-memory-compiler\knowledge",
        "$U\Desktop\SecondBrain\Knowledge"
    )
    $msConfig = "$U\Desktop\DEV\KeystoneOS\data\memory-index-paths.json"
    $msPaths = $null
    if (Test-Path -LiteralPath $msConfig) {
        try {
            $declared = (Get-Content -Raw -LiteralPath $msConfig | ConvertFrom-Json).paths
            if ($declared -and $declared.Count -ge 1) {
                $msPaths = @($declared | ForEach-Object { ($_ -replace '\{HOME\}', $U) -replace '/', '\' })
                Log "INDEX path set: $($msPaths.Count) paths from memory-index-paths.json"
            }
        } catch { Log "INDEX config unreadable ($($_.Exception.Message)) - using built-in fallback list" }
    }
    if (-not $msPaths) {
        $msPaths = $msPathsFallback
        $Errors.Add('memsearch-index-config-missing')
        Log "INDEX path set: built-in fallback ($($msPaths.Count) paths) - memory-index-paths.json not usable"
    }
    # The backup's full reindex shares the SessionEnd hook's lock. Without this,
    # the nightly pass can run beside Claude/Codex hooks and multiply the Python
    # embedding workers. Reclaim only a dead owner; indexers can exceed 30s.
    $indexLockFile = "$U\.claude\global-memory\transcripts\.memsearch-index.lock"
    $indexLockStaleMs = 5 * 60 * 1000
    $haveIndexLock = $false
    try {
        $lockStream = [System.IO.File]::Open($indexLockFile, [System.IO.FileMode]::CreateNew)
        $lockStream.Close()
        [System.IO.File]::WriteAllText($indexLockFile, [string]$PID)
        $haveIndexLock = $true
    }
    catch {
        $ownerAlive = $false
        try {
            $ownerPid = [int](Get-Content -Raw -LiteralPath $indexLockFile)
            $null = Get-Process -Id $ownerPid -ErrorAction Stop
            $ownerAlive = $true
        } catch {}
        if (-not $ownerAlive) {
            $lockStale = $false
            try { $lockStale = (((Get-Date) - (Get-Item -LiteralPath $indexLockFile).LastWriteTime).TotalMilliseconds -ge $indexLockStaleMs) }
            catch { $lockStale = $true }
            if ($lockStale) {
                try {
                    Remove-Item -LiteralPath $indexLockFile -Force -ErrorAction Stop
                    $lockStream = [System.IO.File]::Open($indexLockFile, [System.IO.FileMode]::CreateNew)
                    $lockStream.Close()
                    [System.IO.File]::WriteAllText($indexLockFile, [string]$PID)
                    $haveIndexLock = $true
                } catch {}
            }
        }
    }

    if (-not $haveIndexLock) {
        Log "INDEX skipped - another index run is active; next hook/nightly pass will catch up"
    }
    else {
        try {
            $existingPaths = @($msPaths | Where-Object { Test-Path $_ })
            if ($existingPaths.Count -gt 0) {
                $r = & $msExe index $existingPaths 2>&1 | Select-Object -Last 1
                Log "INDEX full set: $r"
                if ($LASTEXITCODE -ne 0) { $msFail = $true; $Errors.Add("memsearch-index:full-set") }
            }
        }
        finally {
            Remove-Item -LiteralPath $indexLockFile -Force -ErrorAction SilentlyContinue
        }
    }
    if (-not $msFail -and $haveIndexLock) {
        Remove-Item "$U\.claude\global-memory\transcripts\.memsearch-timeout-streak" -Force -ErrorAction SilentlyContinue
        Log "INDEX complete - hook timeout-streak counter reset"
    }
} elseif (-not $msExe) { $Errors.Add('memsearch-exe-missing'); Log "INDEX skipped: memsearch.exe not found" }

# --- 2d. Mirror the recovery guide to the cloud backup root ---
if ((Test-Path 'G:\My Drive') -and (Test-Path "$U\.claude\RESTORE.md") -and -not $DryRun) {
    New-Item -ItemType Directory -Force -Path 'G:\My Drive\Backups' | Out-Null
    Copy-Item "$U\.claude\RESTORE.md" 'G:\My Drive\Backups\RESTORE.md' -Force
    Log "RESTORE.md mirrored to G:\My Drive\Backups\"
}

# --- 3. State + escalation ---
$status = if ($Errors.Count -eq 0) { 'OK' } else { 'ERROR' }
@{
    lastRun  = (Get-Date -Format 'o')
    status   = $status
    errors   = @($Errors)
    okCount  = $Results.Count
    dryRun   = [bool]$DryRun
} | ConvertTo-Json | Set-Content -Path $StateFile

if ($Errors.Count -gt 0 -and -not $DryRun) {
    $line = "[{0}] daily-backup: {1} error(s): {2} - see ~\.claude\scripts\logs\daily-backup.log" -f (Get-Date -Format 'yyyy-MM-dd HH:mm'), $Errors.Count, ($Errors -join ', ')
    Add-Content -Path $ErrorsLog -Value $line
}

# Keep the log from growing unbounded.
if ((Get-Item $LogFile).Length -gt 2MB) {
    Get-Content $LogFile -Tail 2000 | Set-Content $LogFile
}

Log "===== daily-backup end: $status ($($Errors.Count) errors) ====="
if ($Errors.Count -gt 0) { exit 1 } else { exit 0 }

