1	# Read-only health check for Eric's automation/memory stack.
2	# Exit 0 = all clear, exit 1 = issues found (listed in VERDICT).
3	$ErrorActionPreference = 'Continue'
4	$fail = @()
5	
6	function Section($t) { Write-Output "`n=== $t ===" }
7	
8	Section "Scheduled tasks"
9	foreach ($name in 'KeystoneOS Morning', 'KeystoneOS-AgySync', 'MorningBriefing', 'KeystoneOS-DailyBackup', 'KeystoneOS-Rituals') {
10	    try {
11	        $t = Get-ScheduledTask -TaskName $name -ErrorAction Stop
12	        $i = $t | Get-ScheduledTaskInfo
13	        $status = if ($i.LastTaskResult -eq 0) { 'OK' } else { "FAIL(code=$($i.LastTaskResult))" }
14	        if ($i.LastTaskResult -ne 0) { $fail += "task:$name" }
15	        # Judge staleness against the task's OWN schedule, not a flat 30h.
16	        # 'KeystoneOS Morning' runs weekdays, so every Saturday and Sunday it
17	        # tripped a flat threshold and reported a healthy task as broken. A
18	        # check that cries wolf gets ignored, which costs more than no check.
19	        # Stale = it has actually missed its next run, with a 2h grace window.
20	        $age = (New-TimeSpan -Start $i.LastRunTime -End (Get-Date)).TotalHours
21	        $overdueH = if ($i.NextRunTime) { (New-TimeSpan -Start $i.NextRunTime -End (Get-Date)).TotalHours } else { $null }
22	        if ($null -eq $i.NextRunTime -and $age -gt 192) {
23	            $status += " STALE(no next run scheduled, $([math]::Round($age))h since last)"; $fail += "task-stale:$name"
24	        }
25	        elseif ($null -ne $overdueH -and $overdueH -gt 2) {
26	            $status += " OVERDUE($([math]::Round($overdueH))h past its scheduled run)"; $fail += "task-stale:$name"
27	        }
28	        "$name : $status | lastRun=$($i.LastRunTime)"
29	        foreach ($a in $t.Actions) { "  action: $($a.Execute) $($a.Arguments)" }
30	    } catch { "$name : MISSING"; $fail += "task-missing:$name" }
31	}
32	
33	Section "Python venvs"
34	$venvs = @(
35	    "$env:USERPROFILE\Desktop\DEV\morning-briefing\.venv\Scripts\python.exe",
36	    "$env:USERPROFILE\.claude\claude-memory-compiler\.venv\Scripts\python.exe"
37	)
38	foreach ($py in $venvs) {
39	    if (-not (Test-Path $py)) { "$py : MISSING"; $fail += "venv-missing"; continue }
40	    $v = & $py -c "import sys; print(sys.version.split()[0])" 2>&1
41	    if ($LASTEXITCODE -eq 0) { "$py : OK ($v)" } else { "$py : BROKEN -> $v"; $fail += "venv-broken" }
42	}
43	
44	Section "memsearch"
45	$ms = Get-Command memsearch -ErrorAction SilentlyContinue
46	if (-not $ms) { "memsearch: NOT ON PATH"; $fail += "memsearch-path" }
47	else {
48	    "exe: $($ms.Source)"
49	    $out = & memsearch search "healthcheck" --top-k 1 2>&1 | Select-Object -First 3
50	    if ($LASTEXITCODE -eq 0) { "search: OK" } else { "search: FAIL -> $out"; $fail += "memsearch-run" }
51	}
52	
53	Section "Memory pipeline"
54	$errlog = "$env:USERPROFILE\.claude\global-memory\transcripts\.errors.log"
55	if ((Test-Path $errlog) -and ((Get-Item $errlog).Length -gt 0)) {
56	    "errors.log: NON-EMPTY (hook failures below)"; Get-Content $errlog -Tail 5; $fail += "errors-log"
57	} else { "errors.log: clean" }
58	
59	$lastFlush = "$env:USERPROFILE\.claude\claude-memory-compiler\scripts\last-flush.json"
60	if (Test-Path $lastFlush) {
61	    $ageH = (New-TimeSpan -Start (Get-Item $lastFlush).LastWriteTime -End (Get-Date)).TotalHours
62	    if ($ageH -gt 48) { "last-flush.json: STALE ($([math]::Round($ageH))h old)"; $fail += "flush-stale" }
63	    else { "last-flush.json: OK ($([math]::Round($ageH))h ago)" }
64	} else { "last-flush.json: MISSING"; $fail += "flush-missing" }
65	
66	$daily = "$env:USERPROFILE\.claude\claude-memory-compiler\daily"
67	$recent = Get-ChildItem $daily -Filter '*.md' -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 3
