func newNovelPbCmd(flags *rootFlags) *cobra.Command {
	var flagAthlete string
	var flagSquad bool
	var flagMetric string
	var flagVsPeak bool
	var flagWindow string

	cmd := &cobra.Command{
		Use:   "pb",
		Short: "Recent session values vs each athlete's personal best, with readiness % and trend",
		Long: strings.TrimSpace(`
Compares each athlete's most recent session value against their personal best
over the window, printing a readiness index (% of PB) and 3-session trend
arrows.

Use this command to compare an athlete against their OWN historical best.
Do NOT use it to compare against other athletes; use 'benchmark'.`),
		Example:     "  catapult-openfield-connect-pp-cli pb --athlete \"J. Smith\" --metric max_vel --vs-peak --agent",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && cmd.Flags().NFlag() == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return writeDryRun(cmd.OutOrStdout(), flags, "pb")
			}
			if err := validateDataSourceStrategy(flags, "live"); err != nil {
				return err
			}
			ctx, cancel := boundCtx(cmd.Context(), flags)
			defer cancel()
			window, err := cliutil.ParseDurationLoose(flagWindow)
			if err != nil {
				_ = cmd.Usage()
				return usageErr(fmt.Errorf("invalid --window %q: %w", flagWindow, err))
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			now := time.Now()
			start := now.Add(-window)
			rows, err := fetchStatsRows(ctx, c, []string{flagMetric}, []string{"athlete", "activity"},
				[]map[string]any{statsFilter("date", ">=", dayKey(start))})
			if err != nil {
				return classifyAPIError(err, flags)
			}
			actIndex, _, err := fetchActivityIndex(ctx, c, start.AddDate(0, 0, -1), now)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			type sess struct {
				when time.Time
				val  float64
			}
			perAthlete := map[string]*struct {
				name  string
				sess  []sess
			}{}
			for _, r := range rows {
				aid := rowString(r, "athlete_id")
				val, ok := rowNum(r, flagMetric)
				if aid == "" || !ok {
					continue
				}
				when := time.Time{}
				if meta, found := actIndex[rowString(r, "activity_id")]; found {
					when = meta.Start
				}
				a := perAthlete[aid]
				if a == nil {
					a = &struct {
						name string
						sess []sess
					}{name: rowString(r, "athlete_name")}
					perAthlete[aid] = a
				}
				a.sess = append(a.sess, sess{when: when, val: val})
			}
			results := make([]pbRow, 0, len(perAthlete))
			for aid, a := range perAthlete {
				if flagAthlete != "" && !strings.Contains(strings.ToLower(a.name), strings.ToLower(flagAthlete)) {
					continue
				}
				sort.Slice(a.sess, func(i, j int) bool { return a.sess[i].when.Before(a.sess[j].when) })
				var pb float64
				for _, s := range a.sess {
					if s.val > pb {
						pb = s.val
					}
				}
				latest := a.sess[len(a.sess)-1].val
				readiness := 0.0
				if pb > 0 {
					readiness = latest / pb * 100
				}
				trend := ""
				n := len(a.sess)
				for i := max(1, n-3); i < n; i++ {
					switch {
					case a.sess[i].val > a.sess[i-1].val:
						trend += "↑"
					case a.sess[i].val < a.sess[i-1].val:
						trend += "↓"
					default:
						trend += "→"
					}
				}
				results = append(results, pbRow{
					AthleteID:    aid,
					AthleteName:  a.name,
					PB:           round2(pb),
					Latest:       round2(latest),
					ReadinessPct: round2(readiness),
					Trend:        trend,
					Sessions:     n,
				})
			}
			sort.Slice(results, func(i, j int) bool { return results[i].ReadinessPct > results[j].ReadinessPct })
			if !wantsHumanTable(cmd.OutOrStdout(), flags) {
				return printJSONFiltered(cmd.OutOrStdout(), results, flags)
			}
			if len(results) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "No sessions found in the window. Widen --window or check the metric slug.")
				return nil
			}
			fmt.Fprintf(cmd.OutOrStdout(), "%-24s %10s %10s %10s  %s\n", "ATHLETE", "PB", "LATEST", "% OF PB", "TREND")
			for _, r := range results {
				fmt.Fprintf(cmd.OutOrStdout(), "%-24s %10.2f %10.2f %9.1f%%  %s\n", r.AthleteName, r.PB, r.Latest, r.ReadinessPct, r.Trend)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&flagAthlete, "athlete", "", "Filter to athletes whose name contains this text")
	cmd.Flags().BoolVar(&flagSquad, "squad", false, "Show the full squad (default when --athlete is not set)")
	cmd.Flags().StringVar(&flagMetric, "metric", "max_vel", "Metric slug (max velocity by default)")
	cmd.Flags().BoolVar(&flagVsPeak, "vs-peak", true, "Compare against the all-time peak within the window")
	cmd.Flags().StringVar(&flagWindow, "window", "365d", "History window (e.g. 90d, 26w, 1y=365d)")
	return cmd
}
