func (s *Store) upsertItemsTx(tx *sql.Tx, id string, obj map[string]any, data json.RawMessage) error {
	if _, err := tx.Exec(
		`INSERT INTO "items" ("id", "data", "synced_at", "key", "version", "item_type", "title", "abstract_note", "doi", "date", "date_added", "date_modified", "publication_title", "content", "indexed_chars", "total_chars")
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		 ON CONFLICT("id") DO UPDATE SET "data" = excluded."data", "synced_at" = excluded."synced_at", "key" = excluded."key", "version" = excluded."version", "item_type" = excluded."item_type", "title" = excluded."title", "abstract_note" = excluded."abstract_note", "doi" = excluded."doi", "date" = excluded."date", "date_added" = excluded."date_added", "date_modified" = excluded."date_modified", "publication_title" = excluded."publication_title", "content" = excluded."content", "indexed_chars" = excluded."indexed_chars", "total_chars" = excluded."total_chars"`,
		id,
		string(data),
		time.Now().UTC().Format(time.RFC3339),
		lookupFieldValue(obj, "key"),
		lookupFieldValue(obj, "version"),
		lookupFieldValue(obj, "item_type"),
		lookupFieldValue(obj, "title"),
		lookupFieldValue(obj, "abstract_note"),
		lookupFieldValue(obj, "doi"),
		lookupFieldValue(obj, "date"),
		lookupFieldValue(obj, "date_added"),
		lookupFieldValue(obj, "date_modified"),
		lookupFieldValue(obj, "publication_title"),
		lookupFieldValue(obj, "content"),
		lookupFieldValue(obj, "indexed_chars"),
		lookupFieldValue(obj, "total_chars"),
	); err != nil {
		return fmt.Errorf("insert into items: %w", err)
	}

	return nil
}

// UpsertItems inserts or updates a items record with domain-specific columns.
func (s *Store) UpsertItems(data json.RawMessage) error {
	obj, err := DecodeJSONObject(data)
	if err != nil {
		return fmt.Errorf("unmarshaling items: %w", err)
	}

	id := extractObjectID(obj)
	if id == "" {
		return fmt.Errorf("missing id for items")
	}
	storageID := resourceStorageID("items", id, obj)

	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := s.upsertGenericResourceTx(tx, "items", storageID, data); err != nil {
		return err
	}
	if err := s.upsertItemsTx(tx, storageID, obj, data); err != nil {
		return err
	}

	return tx.Commit()
}

// upsertSearchesTx writes the per-resource domain-table portion of a
// searches upsert inside an existing transaction. The caller is
// responsible for the generic resources insert (via upsertGenericResourceTx)
// and for committing the tx. Splitting this out lets UpsertBatch dispatch
// domain inserts per item without opening a per-item transaction.

