// Copyright 2026 Eric Rash and contributors. Licensed under Apache-2.0. See LICENSE.
// Hand-authored novel command: offline research-grounding search.
// pp:data-source local

package cli

import (
	"context"
	"fmt"
	"net/url"
	"sort"
	"strconv"
	"strings"

	"github.com/spf13/cobra"
	"zotero-research-library-pp-cli/internal/store"
)

func init() {
	registerNovelCommand(func(root *cobra.Command, flags *rootFlags) {
		addNovelCommandIfAbsent(root, newNovelGroundCmd(flags))
	})
}

type groundHit struct {
	Key         string  `json:"key"`
	Title       string  `json:"title"`
	Creators    string  `json:"creators,omitempty"`
	Date        string  `json:"date,omitempty"`
	Publication string  `json:"publication,omitempty"`
	DOI         string  `json:"doi,omitempty"`
	ItemType    string  `json:"item_type,omitempty"`
	Snippet     string  `json:"snippet,omitempty"`
	MatchedIn   string  `json:"matched_in"`
	ParentKey   string  `json:"parent_key,omitempty"`
	ParentTitle string  `json:"parent_title,omitempty"`
	rank        float64 `json:"-"`
}

func newNovelGroundCmd(flags *rootFlags) *cobra.Command {
	var flagLimit int
	var flagFulltext bool
	var flagCollection string
	var flagLive bool

	cmd := &cobra.Command{
		Use:   "ground <query>...",
		Short: "Ranked full-text search over your synced library — offline, with snippets and citation-ready metadata",
		Long: `Answers "what does my library say about X?" from the local cache: ranked
FTS5 search over titles, indexed attachment text, abstracts, creators, and
tags, with snippets and citation-ready metadata. No network, no rate limit.

--fulltext restricts matching to indexed attachment text and resolves each
attachment hit to its parent paper. --live bypasses the cache and runs the
query server-side via the API's qmode=everything search grammar.`,
		Example: `  zotero-research-library-pp-cli ground "hamstring injury prevention" --limit 10 --agent
  zotero-research-library-pp-cli ground "nordic hamstring" --fulltext --agent
  zotero-research-library-pp-cli ground "acl injury" --collection HAMSTRING --limit 5`,
		Args:        cobra.MinimumNArgs(1),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				return nil
			}
			query := strings.TrimSpace(strings.Join(args, " "))
			if query == "" {
				return fmt.Errorf("query must not be empty")
			}
			if flagLimit <= 0 {
				flagLimit = 10
			}

			if flagLive {
				return groundLive(cmd, flags, query, flagLimit)
			}

			ctx := cmd.Context()
			db, err := requireLocalCache(ctx, "zotero-research-library-pp-cli")
			if err != nil {
				return err
			}
			defer db.Close()

			collectionKey := ""
			if flagCollection != "" {
				collectionKey, err = resolveCollectionKey(ctx, db, flagCollection)
				if err != nil {
					return err
				}
			}

			hits, err := groundSearch(ctx, db, query, flagLimit, flagFulltext, collectionKey)
			if err != nil {
				return err
			}

			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"query":   query,
					"source":  "local",
					"count":   len(hits),
					"results": hits,
				}, flags)
			}
			if len(hits) == 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "No matches for %q in the local cache.\n", query)
				fmt.Fprintln(cmd.OutOrStdout(), "If the cache may be stale, run 'sync' — or retry with --live for a server-side search.")
				return nil
			}
			out := cmd.OutOrStdout()
			for i, h := range hits {
				fmt.Fprintf(out, "%2d. %s", i+1, h.Title)
				if h.Creators != "" {
					fmt.Fprintf(out, " — %s", h.Creators)
				}
				if h.Date != "" {
					fmt.Fprintf(out, " (%s)", h.Date)
				}
				fmt.Fprintf(out, "\n    key=%s", h.Key)
				if h.DOI != "" {
					fmt.Fprintf(out, "  doi=%s", h.DOI)
				}
				if h.Publication != "" {
					fmt.Fprintf(out, "  %s", h.Publication)
				}
				fmt.Fprintln(out)
				if h.Snippet != "" {
					fmt.Fprintf(out, "    %s\n", h.Snippet)
				}
			}
			return nil
		},
	}
	cmd.Flags().IntVar(&flagLimit, "limit", 10, "Maximum results to return")
	cmd.Flags().BoolVar(&flagFulltext, "fulltext", false, "Match only indexed attachment full text; resolve hits to parent papers")
	cmd.Flags().StringVar(&flagCollection, "collection", "", "Restrict to a collection (key or name)")
	cmd.Flags().BoolVar(&flagLive, "live", false, "Run the query server-side (qmode=everything) instead of the local cache")
	return cmd
}

// groundSearch runs the ranked local search. Primary source is items_fts
// (title + indexed attachment content); a secondary pass over resources_fts
// catches creator/tag/abstract-only matches items_fts cannot see.
func groundSearch(ctx context.Context, db *store.Store, query string, limit int, fulltextOnly bool, collectionKey string) ([]groundHit, error) {
	match := ftsQuote(query)
	if fulltextOnly {
		match = "content: (" + match + ")"
	}

	collectionFilter := ""
	var collectionArgs []any
	if collectionKey != "" {
		collectionFilter = ` AND EXISTS (SELECT 1 FROM json_each(json_extract(i."data", '$.data.collections')) je WHERE je.value = ?)`
		collectionArgs = append(collectionArgs, collectionKey)
	}

	primarySQL := `SELECT i."data", snippet("items_fts", 1, '[', ']', ' … ', 12), bm25("items_fts")
		FROM "items_fts" JOIN "items" i ON i.rowid = "items_fts".rowid
		WHERE "items_fts" MATCH ?` + collectionFilter + `
		ORDER BY bm25("items_fts") LIMIT ?`
	args := append([]any{match}, collectionArgs...)
	args = append(args, limit*2)

	rows, err := db.DB().QueryContext(ctx, primarySQL, args...)
	if err != nil {
		return nil, fmt.Errorf("local search: %w", err)
	}
	defer rows.Close()

	seen := map[string]bool{}
	var hits []groundHit
	for rows.Next() {
		var raw []byte
		var snip string
		var rank float64
		if err := rows.Scan(&raw, &snip, &rank); err != nil {
			return nil, err
		}
		h, ok := buildGroundHit(ctx, db, raw, snip, rank, "title/fulltext", fulltextOnly)
		if !ok || seen[h.Key] {
			continue
		}
		seen[h.Key] = true
		hits = append(hits, h)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	// Secondary pass: creators, tags, and abstracts live in the extracted
	// leaf values of resources_fts, not in items_fts.
	if !fulltextOnly {
		secondarySQL := `SELECT i."data", bm25("resources_fts")
			FROM "resources_fts"
			JOIN "resources" r ON r.rowid = "resources_fts".rowid
			JOIN "items" i ON i."id" = r.id
			WHERE r.resource_type = 'items' AND "resources_fts" MATCH ?` + collectionFilter + `
			ORDER BY bm25("resources_fts") LIMIT ?`
		sArgs := append([]any{ftsQuote(query)}, collectionArgs...)
		sArgs = append(sArgs, limit*2)
		srows, err := db.DB().QueryContext(ctx, secondarySQL, sArgs...)
		if err == nil {
			defer srows.Close()
			for srows.Next() {
				var raw []byte
				var rank float64
				if err := srows.Scan(&raw, &rank); err != nil {
					break
				}
				h, ok := buildGroundHit(ctx, db, raw, "", rank+1, "creators/tags/abstract", false)
				if !ok || seen[h.Key] {
					continue
				}
				seen[h.Key] = true
				hits = append(hits, h)
			}
		}
	}

	sort.SliceStable(hits, func(a, b int) bool { return hits[a].rank < hits[b].rank })
	if len(hits) > limit {
		hits = hits[:limit]
	}
	return hits, nil
}

// buildGroundHit decodes a stored item row into a result. Attachment and note
// rows resolve to their parent paper when one exists; in --fulltext mode the
// attachment's snippet is kept while the citation metadata comes from the
// parent.
func buildGroundHit(ctx context.Context, db *store.Store, raw []byte, snippet string, rank float64, matchedIn string, resolveParent bool) (groundHit, bool) {
	d, err := decodeItemData(raw)
	if err != nil || d.Key == "" {
		return groundHit{}, false
	}
	h := groundHit{
		Key:         d.Key,
		Title:       d.Title,
		Creators:    creatorSummary(d.Creators),
		Date:        d.Date,
		Publication: d.PublicationTitle,
		DOI:         d.DOI,
		ItemType:    d.ItemType,
		Snippet:     strings.TrimSpace(snippet),
		MatchedIn:   matchedIn,
		rank:        rank,
	}
	if (d.ItemType == "attachment" || d.ItemType == "note") && d.ParentItem != "" {
		var parentRaw []byte
		row := db.DB().QueryRowContext(ctx, `SELECT "data" FROM "items" WHERE "key" = ?`, d.ParentItem)
		if err := row.Scan(&parentRaw); err == nil {
			if p, perr := decodeItemData(parentRaw); perr == nil && p.Key != "" {
				h.ParentKey = d.Key
				h.ParentTitle = d.Title
				h.Key = p.Key
				h.Title = p.Title
				h.Creators = creatorSummary(p.Creators)
				h.Date = p.Date
				h.Publication = p.PublicationTitle
				h.DOI = p.DOI
				h.ItemType = p.ItemType
				h.MatchedIn = "attachment fulltext"
			}
		} else if resolveParent {
			// --fulltext promised parent resolution; an orphan attachment
			// still surfaces under its own identity.
			h.MatchedIn = "attachment fulltext (parent not in cache)"
		}
	}
	if h.Title == "" {
		return groundHit{}, false
	}
	return h, true
}

// groundLive runs the query server-side via the generated items endpoint's
// full search grammar (qmode=everything covers server-side full text).
func groundLive(cmd *cobra.Command, flags *rootFlags, query string, limit int) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	params := url.Values{}
	params.Set("q", query)
	params.Set("qmode", "everything")
	params.Set("limit", strconv.Itoa(limit))
	data, _, err := c.Get(cmd.Context(), "/items", params)
	if err != nil {
		return classifyAPIError(err, flags)
	}
	if flags.asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
			"query":   query,
			"source":  "live",
			"results": data,
		}, flags)
	}
	fmt.Fprintln(cmd.OutOrStdout(), string(data))
	return nil
}

