				var raw []byte
				if err := rows.Scan(&raw); err != nil {
					return err
				}
				d, err := decodeItemData(raw)
				if err != nil || d.Key == "" {
					continue
				}
				items = append(items, recentItem{
					Key:       d.Key,
					Title:     d.Title,
					Creators:  creatorSummary(d.Creators),
					ItemType:  d.ItemType,
					DateAdded: d.DateAdded,
					DOI:       d.DOI,
				})
			}
			if err := rows.Err(); err != nil {
