124						fmt.Fprintf(cmd.ErrOrStderr(), "  %d/%d attachments processed\n", i+1, len(keys))
125					}
126				}
127	
128				if failed == 0 && flagLimit <= 0 {
129					_ = db.SaveSyncCursor(fulltextCursorResource, strconv.FormatInt(maxVersion, 10))
130				}
131	
132				if flags.asJSON {
133					return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
134						"changed": len(changed),
135						"indexed": indexed,
136						"missing": missing,
137						"failed":  failed,
138						"cursor":  maxVersion,
139					}, flags)
140				}
141				fmt.Fprintf(cmd.OutOrStdout(), "Indexed full text for %d attachments (%d had none, %d failed) — 'ground --fulltext' is ready.\n", indexed, missing, failed)
142				return nil
143			},
144		}
145		cmd.Flags().IntVar(&flagLimit, "limit", 0, "Cap attachments fetched this run (0 = all changed)")
146		return cmd
147	}

