// Copyright 2026 Eric Rash and contributors. Licensed under Apache-2.0. See LICENSE.
// Hand-authored novel command: offline research-grounding search.
// pp:data-source local

package cli

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/spf13/cobra"
	"zotero-research-library-pp-cli/internal/store"
)

func init() {
	registerNovelCommand(func(root *cobra.Command, flags *rootFlags) {
		addNovelCommandIfAbsent(root, newNovelGroundCmd(flags))
	})
}

type groundHit struct {
	Key         string  `json:"key"`
	Title       string  `json:"title"`
	Creators    string  `json:"creators,omitempty"`
	Date        string  `json:"date,omitempty"`
	Publication string  `json:"publication,omitempty"`
	DOI         string  `json:"doi,omitempty"`
	ItemType    string  `json:"item_type,omitempty"`
	Snippet     string  `json:"snippet,omitempty"`
	MatchedIn   string  `json:"matched_in"`
	ParentKey   string  `json:"parent_key,omitempty"`
	ParentTitle string  `json:"parent_title,omitempty"`
	rank        float64 `json:"-"`
}

func newNovelGroundCmd(flags *rootFlags) *cobra.Command {
	var flagLimit int
	var flagFulltext bool
	var flagCollection string
	var flagLive bool

	cmd := &cobra.Command{
		Use:   "ground <query>...",
		Short: "Ranked full-text search over your synced library — offline, with snippets and citation-ready metadata",
		Long: `Answers "what does my library say about X?" from the local cache: ranked
FTS5 search over titles, abstracts, creators, and tags, with snippets and
citation-ready metadata. No network, no rate limit.

--fulltext matches indexed attachment text (populate it once with
'cache index-fulltext') and resolves each hit to its parent paper. --live
bypasses the cache and runs the query server-side via qmode=everything.`,
		Example: `  zotero-research-library-pp-cli ground "hamstring injury prevention" --limit 10 --agent
  zotero-research-library-pp-cli ground "nordic hamstring" --fulltext --agent
  zotero-research-library-pp-cli ground "acl injury" --collection HAMSTRING --limit 5`,
		Args:        cobra.MinimumNArgs(1),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				return nil
			}
			query := strings.TrimSpace(strings.Join(args, " "))
			if query == "" {
				return fmt.Errorf("query must not be empty")
			}
			if flagLimit <= 0 {
				flagLimit = 10
			}

			if flagLive {
				return groundLive(cmd, flags, query, flagLimit)
			}

			ctx := cmd.Context()
			db, err := requireLocalCache(ctx, "zotero-research-library-pp-cli")
			if err != nil {
				return err
			}
			defer db.Close()

			collectionKey := ""
			if flagCollection != "" {
				collectionKey, err = resolveCollectionKey(ctx, db, flagCollection)
				if err != nil {
					return err
				}
			}

			hits, err := groundSearch(ctx, db, query, flagLimit, flagFulltext, collectionKey)
			if err != nil {
				return err
			}

			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"query":   query,
					"source":  "local",
					"count":   len(hits),
					"results": hits,
				}, flags)
			}
			out := cmd.OutOrStdout()
			if len(hits) == 0 {
				fmt.Fprintf(out, "No matches for %q in the local cache.\n", query)
				if flagFulltext {
					fmt.Fprintln(out, "Attachment text must be indexed first: run 'cache index-fulltext'.")
				} else {
					fmt.Fprintln(out, "If the cache may be stale, run 'sync' — or retry with --live for a server-side search.")
				}
				return nil
			}
			for i, h := range hits {
				fmt.Fprintf(out, "%2d. %s", i+1, h.Title)
				if h.Creators != "" {
					fmt.Fprintf(out, " — %s", h.Creators)
				}
				if h.Date != "" {
					fmt.Fprintf(out, " (%s)", h.Date)
				}
				fmt.Fprintf(out, "\n    key=%s", h.Key)
				if h.DOI != "" {
					fmt.Fprintf(out, "  doi=%s", h.DOI)
				}
				if h.Publication != "" {
					fmt.Fprintf(out, "  %s", h.Publication)
				}
				fmt.Fprintln(out)
				if h.Snippet != "" {
					fmt.Fprintf(out, "    %s\n", h.Snippet)
				}
			}
			return nil
		},
	}
	cmd.Flags().IntVar(&flagLimit, "limit", 10, "Maximum results to return")
	cmd.Flags().BoolVar(&flagFulltext, "fulltext", false, "Match indexed attachment full text (see 'cache index-fulltext'); resolve hits to parent papers")
	cmd.Flags().StringVar(&flagCollection, "collection", "", "Restrict to a collection (key or name)")
	cmd.Flags().BoolVar(&flagLive, "live", false, "Run the query server-side (qmode=everything) instead of the local cache")
	return cmd
}

// groundSearch runs the ranked local search. The primary source is
// resources_fts, whose content column holds every searchable leaf value of
// the item JSON (title, abstract, creators, tags). A second pass over
// items_fts covers attachment full text populated by 'cache index-fulltext';
// in --fulltext mode that pass is the only source.
func groundSearch(ctx context.Context, db *store.Store, query string, limit int, fulltextOnly bool, collectionKey string) ([]groundHit, error) {
	match := ftsQuote(query)

	collectionFilter := ""
	var collectionArgs []any
	if collectionKey != "" {
		collectionFilter = ` AND EXISTS (SELECT 1 FROM json_each(json_extract(i."data", '$.data.collections')) je WHERE je.value = ?)`
		collectionArgs = append(collectionArgs, collectionKey)
	}

	seen := map[string]bool{}
	var hits []groundHit

	if !fulltextOnly {
		primarySQL := `SELECT i."data", snippet("resources_fts", 2, '[', ']', ' … ', 12), bm25("resources_fts")
			FROM "resources_fts"
			JOIN "resources" r ON r.rowid = "resources_fts".rowid
			JOIN "items" i ON i."id" = r.id
			WHERE r.resource_type = 'items' AND "resources_fts" MATCH ?` + collectionFilter + `
			ORDER BY bm25("resources_fts") LIMIT ?`
		args := append([]any{match}, collectionArgs...)
		args = append(args, limit*2)
		rows, err := db.DB().QueryContext(ctx, primarySQL, args...)
		if err != nil {
			return nil, fmt.Errorf("local search: %w", err)
		}
		defer rows.Close()
		for rows.Next() {
			var raw []byte
			var snip string
			var rank float64
			if err := rows.Scan(&raw, &snip, &rank); err != nil {
				return nil, err
			}
			h, ok := buildGroundHit(ctx, db, raw, snip, rank, "metadata", false)
			if !ok || seen[h.Key] {
				continue
			}
			seen[h.Key] = true
			hits = append(hits, h)
		}
		if err := rows.Err(); err != nil {
			return nil, err
		}
	}

	// Attachment full text lives in the items.content column (populated by
	// 'cache index-fulltext') and is indexed by items_fts.
	fulltextSQL := `SELECT i."data", snippet("items_fts", 1, '[', ']', ' … ', 12), bm25("items_fts")
		FROM "items_fts" JOIN "items" i ON i.rowid = "items_fts".rowid
		WHERE "items_fts" MATCH ?` + collectionFilter + `
		ORDER BY bm25("items_fts") LIMIT ?`
	fArgs := append([]any{"content: (" + match + ")"}, collectionArgs...)
	fArgs = append(fArgs, limit*2)
	frows, err := db.DB().QueryContext(ctx, fulltextSQL, fArgs...)
	if err == nil {
		defer frows.Close()
		for frows.Next() {
			var raw []byte
			var snip string
			var rank float64
			if err := frows.Scan(&raw, &snip, &rank); err != nil {
				break
			}
			// Full-text matches rank slightly behind exact metadata matches
			// unless --fulltext asked for them specifically.
			adj := rank
			if !fulltextOnly {
				adj += 0.5
			}
			h, ok := buildGroundHit(ctx, db, raw, snip, adj, "attachment fulltext", true)
			if !ok || seen[h.Key] {
				continue
			}
			seen[h.Key] = true
			hits = append(hits, h)
		}
	}

	sort.SliceStable(hits, func(a, b int) bool { return hits[a].rank < hits[b].rank })
	if len(hits) > limit {
		hits = hits[:limit]
	}
	return hits, nil
}

// buildGroundHit decodes a stored item row into a result. Attachment and note
// rows resolve to their parent paper when one exists, keeping the attachment's
// snippet while citation metadata comes from the parent.
func buildGroundHit(ctx context.Context, db *store.Store, raw []byte, snippet string, rank float64, matchedIn string, resolveParent bool) (groundHit, bool) {
	d, err := decodeItemData(raw)
	if err != nil || d.Key == "" {
		return groundHit{}, false
	}
	h := groundHit{
		Key:         d.Key,
		Title:       d.Title,
		Creators:    creatorSummary(d.Creators),
		Date:        d.Date,
		Publication: d.PublicationTitle,
		DOI:         d.DOI,
		ItemType:    d.ItemType,
		Snippet:     strings.TrimSpace(snippet),
		MatchedIn:   matchedIn,
		rank:        rank,
	}
	if (d.ItemType == "attachment" || d.ItemType == "note") && d.ParentItem != "" {
		var parentRaw []byte
		row := db.DB().QueryRowContext(ctx, `SELECT "data" FROM "items" WHERE "id" = ?`, d.ParentItem)
		if err := row.Scan(&parentRaw); err == nil {
			if p, perr := decodeItemData(parentRaw); perr == nil && p.Key != "" {
				h.ParentKey = d.Key
				h.ParentTitle = d.Title
				h.Key = p.Key
				h.Title = p.Title
				h.Creators = creatorSummary(p.Creators)
				h.Date = p.Date
				h.Publication = p.PublicationTitle
				h.DOI = p.DOI
				h.ItemType = p.ItemType
			}
		} else if resolveParent {
			h.MatchedIn = matchedIn + " (parent not in cache)"
		}
	}
	// Attachments matched only on filename noise aren't research results.
	if h.Title == "" {
		return groundHit{}, false
	}
	return h, true
}

// groundLive runs the query server-side via the generated items endpoint's
// full search grammar (qmode=everything covers server-side full text).
func groundLive(cmd *cobra.Command, flags *rootFlags, query string, limit int) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	params := map[string]string{
		"q":     query,
		"qmode": "everything",
		"limit": strconv.Itoa(limit),
	}
	data, err := c.Get(cmd.Context(), "/items", params)
	if err != nil {
		return classifyAPIError(err, flags)
	}
	if flags.asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
			"query":   query,
			"source":  "live",
			"results": data,
		}, flags)
	}
	fmt.Fprintln(cmd.OutOrStdout(), string(data))
	return nil
}

// Copyright 2026 Eric Rash and contributors. Licensed under Apache-2.0. See LICENSE.
// Hand-authored helpers shared by the novel commands (ground, items recent,
// cite, collections tree, cache status/reindex). Kept out of generated files
// so regen-merge preserves them.

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"zotero-research-library-pp-cli/internal/client"
	"zotero-research-library-pp-cli/internal/store"
)

// apiErrStatus extracts the HTTP status from a client error, or 0.
func apiErrStatus(err error) int {
	var apiErr *client.APIError
	if errors.As(err, &apiErr) {
		return apiErr.StatusCode
	}
	return 0
}

// zoteroItemData is the subset of a Zotero item's nested `data` object the
// novel commands read. The API envelope is {key, version, data:{...}}.
type zoteroItemData struct {
	Key              string          `json:"key"`
	ItemType         string          `json:"itemType"`
	Title            string          `json:"title"`
	AbstractNote     string          `json:"abstractNote"`
	Date             string          `json:"date"`
	DateAdded        string          `json:"dateAdded"`
	DOI              string          `json:"DOI"`
	PublicationTitle string          `json:"publicationTitle"`
	Extra            string          `json:"extra"`
	ParentItem       string          `json:"parentItem"`
	Collections      []string        `json:"collections"`
	Creators         []zoteroCreator `json:"creators"`
}

type zoteroCreator struct {
	CreatorType string `json:"creatorType"`
	FirstName   string `json:"firstName"`
	LastName    string `json:"lastName"`
	Name        string `json:"name"`
}

// decodeItemData unwraps the nested `data` object from a stored item envelope.
func decodeItemData(raw []byte) (zoteroItemData, error) {
	var envelope struct {
		Key  string         `json:"key"`
		Data zoteroItemData `json:"data"`
	}
	if err := json.Unmarshal(raw, &envelope); err != nil {
		return zoteroItemData{}, err
	}
	d := envelope.Data
	if d.Key == "" {
		d.Key = envelope.Key
	}
	return d, nil
}

// creatorSummary renders "Last, Last & Last" (capped at three surnames) for
// human and JSON output. Institutional creators use their single Name field.
func creatorSummary(creators []zoteroCreator) string {
	var names []string
	for _, c := range creators {
		switch {
		case c.LastName != "":
			names = append(names, c.LastName)
		case c.Name != "":
			names = append(names, c.Name)
		}
	}
	if len(names) == 0 {
		return ""
	}
	if len(names) > 3 {
		return strings.Join(names[:3], ", ") + " et al."
	}
	if len(names) > 1 {
		return strings.Join(names[:len(names)-1], ", ") + " & " + names[len(names)-1]
	}
	return names[0]
}

// ftsQuote wraps every user-supplied term as a quoted FTS5 string so
// punctuation (hyphens, apostrophes, colons) can't be parsed as FTS syntax.
func ftsQuote(query string) string {
	terms := strings.Fields(query)
	quoted := make([]string, 0, len(terms))
	for _, t := range terms {
		quoted = append(quoted, `"`+strings.ReplaceAll(t, `"`, `""`)+`"`)
	}
	return strings.Join(quoted, " ")
}

// resolveCollectionKey resolves a user-supplied collection reference — exact
// key first, then case-insensitive name match — against the local cache.
func resolveCollectionKey(ctx context.Context, db *store.Store, ref string) (string, error) {
	row := db.DB().QueryRowContext(ctx,
		`SELECT "key" FROM "collections" WHERE "key" = ?`, ref)
	var key string
	if err := row.Scan(&key); err == nil {
		return key, nil
	}
	rows, err := db.DB().QueryContext(ctx,
		`SELECT "key", "name" FROM "collections" WHERE LOWER("name") LIKE LOWER(?) ORDER BY "name" LIMIT 5`,
		"%"+ref+"%")
	if err != nil {
		return "", err
	}
	defer rows.Close()
	var matches [][2]string
	for rows.Next() {
		var k, n string
		if err := rows.Scan(&k, &n); err != nil {
			return "", err
		}
		matches = append(matches, [2]string{k, n})
	}
	if err := rows.Err(); err != nil {
		return "", err
	}
	switch len(matches) {
	case 0:
		return "", fmt.Errorf("no collection matches %q (run 'collections tree' to browse)", ref)
	case 1:
		return matches[0][0], nil
	default:
		var names []string
		for _, m := range matches {
			names = append(names, fmt.Sprintf("%s (%s)", m[1], m[0]))
		}
		return "", fmt.Errorf("collection %q is ambiguous: %s", ref, strings.Join(names, ", "))
	}
}

// requireLocalCache opens the store read-only and converts the two empty
// states (no DB file, open error) into actionable messages.
func requireLocalCache(ctx context.Context, cliName string) (*store.Store, error) {
	db, err := openStoreForRead(ctx, cliName)
	if err != nil {
		return nil, fmt.Errorf("opening local cache: %w", err)
	}
	if db == nil {
		return nil, fmt.Errorf("local cache is empty — run '%s sync --full' first", cliName)
	}
	return db, nil
}

