130	// hasCitationKey confirms the extra field pins exactly this citekey — the SQL
131	// LIKE above is only a prefilter and would also match citekey prefixes.
132	func hasCitationKey(extra, citekey string) bool {
133		for _, line := range strings.Split(extra, "\n") {
134			line = strings.TrimSpace(line)
135			if v, ok := strings.CutPrefix(line, "Citation Key:"); ok && strings.TrimSpace(v) == citekey {
136				return true
137			}
138		}
139		return false
140	}
141	
142	// bbtExport asks Better BibTeX to export one citekey as BibTeX.
143	func bbtExport(ctx context.Context, citekey string) (string, error) {
144		body, err := json.Marshal(map[string]any{
145			"jsonrpc": "2.0",
146			"method":  "item.export",
147			"params":  []any{[]string{citekey}, "betterbibtex"},
148			"id":      1,
149		})
150		if err != nil {
151			return "", err
152		}
153		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
154		defer cancel()
155		req, err := http.NewRequestWithContext(ctx, http.MethodPost, bbtEndpoint, bytes.NewReader(body))
156		if err != nil {
157			return "", err
158		}
159		req.Header.Set("Content-Type", "application/json")
160		req.Header.Set("Accept", "application/json")
161		resp, err := http.DefaultClient.Do(req)
162		if err != nil {
163			return "", err
164		}
165		defer resp.Body.Close()
166		var rpc struct {
167			Result json.RawMessage `json:"result"`
168			Error  *struct {
169				Message string `json:"message"`
170			} `json:"error"`
171		}
172		if err := json.NewDecoder(resp.Body).Decode(&rpc); err != nil {
173			return "", fmt.Errorf("decoding Better BibTeX response: %w", err)
174		}
175		if rpc.Error != nil {
176			return "", fmt.Errorf("better bibtex: %s", rpc.Error.Message)
177		}
178		// item.export returns either a plain string or [status, mime, body].
179		var asString string
180		if json.Unmarshal(rpc.Result, &asString) == nil && asString != "" {
181			return strings.TrimSpace(asString), nil
182		}
183		var asTuple []any
184		if json.Unmarshal(rpc.Result, &asTuple) == nil && len(asTuple) >= 3 {
185			if s, ok := asTuple[2].(string); ok && s != "" {
186				return strings.TrimSpace(s), nil
187			}
188		}
189		return "", fmt.Errorf("citekey %q not found by Better BibTeX", citekey)
190	}

