147	// groundSearch runs the ranked local search. The primary source is
148	// resources_fts, whose content column holds every searchable leaf value of
149	// the item JSON (title, abstract, creators, tags). A second pass over
150	// items_fts covers attachment full text populated by 'cache index-fulltext';
151	// in --fulltext mode that pass is the only source.
152	func groundSearch(ctx context.Context, db *store.Store, query string, limit int, fulltextOnly bool, collectionKey string) ([]groundHit, error) {
